import marshal
import builtins
import re

# Interceptamos print
_print_orig = builtins.print
def _print_custom(*args, **kwargs):
    new_args = []
    for a in args:
        text = str(a)
        text = re.sub(r'ibrahin', 'Sosa', text, flags=re.IGNORECASE)
        text = text.replace("\033[35m", "\033[34m").replace("\033[95m", "\033[94m")
        text = text.replace("\033[37m", "\033[32m").replace("\033[97m", "\033[92m").replace("\033[0m", "\033[32m")
        new_args.append(text)
    _print_orig(*new_args, **kwargs)
builtins.print = _print_custom

# Interceptamos input para limpiar las rutas que piden datos
_input_orig = builtins.input
def _input_custom(prompt=None):
    if prompt:
        prompt = str(prompt)
        prompt = re.sub(r'ibrahin', 'Sosa', prompt, flags=re.IGNORECASE)
    return _input_orig(prompt)
builtins.input = _input_custom

